      title: "Playground",
      url: "#",
    },
    {
      icon: BotIcon,
      items: [
        {
          title: "Genesis",
          url: "#",
        },
        {
          title: "Explorer",
          url: "#",
        },
        {
          title: "Quantum",
          url: "#",
        },
      ],
      title: "Models",
      url: "#",
    },
    {
      icon: BookOpenIcon,
      items: [
        {
          title: "Introduction",
          url: "#",
        },
        {
          title: "Get Started",
          url: "#",
        },
        {
          title: "Tutorials",
          url: "#",
        },
        {
          title: "Changelog",
          url: "#",
        },
      ],
      title: "Documentation",
      url: "#",
    },
    {
      icon: BrainIcon,
      items: [],
      title: "Ask",
      url: "/ask",
    },
    {
      icon: NewspaperIcon,
      items: [],
      title: "Digest",
      url: "/digest",
    },
    {
      icon: MicIcon,
      items: [],
      title: "Capture",
      url: "/capture",
    },
    {
      icon: ClipboardCheckIcon,
      items: [],
      title: "Review",
      url: "/review",
    },
    {
