143	export const ReviewForm = ({ proposal }: { proposal: ReviewProposal }) => {
144	  const router = useRouter();
145	  const [isPending, startTransition] = useTransition();
146	  const [error, setError] = useState<string | null>(null);
147	  const [entityChoices, setEntityChoices] = useState<
148	    Record<string, EntityChoice | undefined>
149	  >({});
150	  const [factSelections, setFactSelections] = useState<
151	    Record<number, FactSelection | undefined>
152	  >({});
153	
154	  const chooseEntity = useCallback((draftId: string, choice: Choice) => {
155	    setEntityChoices((previous) => ({ ...previous, [draftId]: choice }));
156	  }, []);
157	
158	  const chooseFact = useCallback(
159	    (index: number, originalText: string, choice: Choice) => {
160	      setFactSelections((previous) => ({
161	        ...previous,
162	        [index]:
163	          choice === undefined
164	            ? undefined
165	            : { choice, text: previous[index]?.text ?? originalText },
166	      }));
167	    },
168	    []
169	  );
170	
171	  const changeFactText = useCallback((index: number, text: string) => {
172	    setFactSelections((previous) => ({
173	      ...previous,
174	      [index]: { choice: previous[index]?.choice ?? "confirm", text },
175	    }));
176	  }, []);
177	
178	  const pendingEntities = proposal.entityDrafts.filter(
179	    (draft) => draft.resolutionStatus === "pending"
180	  );
181	  const pendingFacts = proposal.factDrafts.filter(
182	    (draft) => draft.resolutionStatus === "pending"
183	  );
184	  const decidedCount =
185	    Object.values(entityChoices).filter(Boolean).length +
186	    Object.values(factSelections).filter(Boolean).length;
187	
188	  const submit = useCallback(() => {
189	    setError(null);
190	    startTransition(async () => {
191	      const originalTexts: Record<number, string> = {};
192	      for (const draft of proposal.factDrafts) {
193	        originalTexts[draft.index] = draft.text;
194	      }
195	      const result = await resolveProposal(
196	        proposal.id,
197	        { entities: entityChoices, facts: factSelections },
198	        originalTexts
199	      );
200	      if (result.error) {
201	        setError(result.error);
202	        return;
203	      }
204	      if (result.proposalResolved) {
205	        router.push("/review");
206	      } else {
207	        setEntityChoices({});
208	        setFactSelections({});
209	        router.refresh();
210	      }
211	    });
212	  }, [entityChoices, factSelections, proposal, router]);
213	
214	  if (pendingEntities.length === 0 && pendingFacts.length === 0) {
215	    return (
216	      <div className="flex min-h-20 items-center justify-center rounded-xl bg-muted/50 text-muted-foreground text-sm">
217	        Everything in this proposal has been reviewed.
218	      </div>
219	    );
220	  }
221	
222	  return (
223	    <div className="flex flex-col gap-4">
224	      {pendingEntities.length > 0 ? (
225	        <Card>
226	          <CardHeader>
227	            <CardTitle className="text-base">New entities</CardTitle>
228	          </CardHeader>
229	          <CardContent className="flex flex-col gap-3">
230	            {pendingEntities.map((draft) => (
231	              <EntityRow
232	                choice={entityChoices[draft.draftId]}
233	                draftId={draft.draftId}
234	                entityType={draft.entityType}
235	                key={draft.draftId}
236	                name={entityName(draft.data)}
237	                onChoose={chooseEntity}
238	              />
239	            ))}
240	          </CardContent>
241	        </Card>
242	      ) : null}
243	
244	      {pendingFacts.length > 0 ? (
245	        <Card>
246	          <CardHeader>
247	            <CardTitle className="text-base">Facts</CardTitle>
248	          </CardHeader>
249	          <CardContent className="flex flex-col gap-5">
250	            {pendingFacts.map((draft) => (
251	              <FactRow
252	                draft={draft}
253	                key={draft.index}
254	                onChoose={chooseFact}
255	                onTextChange={changeFactText}
256	                selection={factSelections[draft.index]}
257	              />
258	            ))}
259	          </CardContent>
260	        </Card>
261	      ) : null}
262	
263	      {error ? <p className="text-destructive text-sm">{error}</p> : null}
264	      <div className="flex items-center gap-3">
265	        <Button disabled={decidedCount === 0 || isPending} onClick={submit}>
266	          {isPending
267	            ? "Saving…"
268	            : `Apply ${decidedCount} decision${decidedCount === 1 ? "" : "s"}`}
269	        </Button>
270	        <span className="text-muted-foreground text-sm">
271	          Undecided items stay open for later.
272	        </span>
273	      </div>
274	    </div>
275	  );
276	};
