import { describe, expect, test } from "bun:test";
import type { Db } from "mongodb";
import { ObjectId } from "mongodb";
import { retrieveFacts } from "../retrieval";
import type { Fact } from "../schemas";

// `$search`/`$vectorSearch` need mongot, so the pipeline itself only runs
// against Atlas. The composition around it — rerank wiring and its failure
// fallback — is pure control flow and is tested here with a stubbed Db.
const fact = (text: string): Fact =>
  ({
    _id: new ObjectId(),
    category: "background",
    confidence: 0.9,
    tenantId: "tenant-1",
    text,
  }) as unknown as Fact;

const stubDb = (fused: Fact[]): Db =>
  ({
    collection: () => ({
      aggregate: () => ({
        toArray: () => Promise.resolve(fused),
      }),
    }),
  }) as unknown as Db;

describe("retrieveFacts rerank handling", () => {
  test("returns reranked order with relevance scores", async () => {
    const [a, b] = [fact("a"), fact("b")];
    const results = await retrieveFacts(stubDb([a, b]), {
      query: "q",
      rerank: (_query, documents) =>
        Promise.resolve(
          [...documents].reverse().map((document, index) => ({
            document,
            relevanceScore: 1 - index * 0.1,
          }))
        ),
      tenantId: "tenant-1",
    });
    expect(results.map((r) => r.fact.text)).toEqual(["b", "a"]);
    expect(results[0]?.relevanceScore).toBe(1);
  });

  test("falls back to fusion order when the reranker throws", async () => {
    const [a, b] = [fact("a"), fact("b")];
    const results = await retrieveFacts(stubDb([a, b]), {
      query: "q",
      rerank: () => Promise.reject(new Error("rerank 403: bad key")),
      tenantId: "tenant-1",
    });
    expect(results.map((r) => r.fact.text)).toEqual(["a", "b"]);
    expect(results[0]?.relevanceScore).toBeUndefined();
  });

  test("skips reranking entirely when no candidates fused", async () => {
    let called = false;
    const results = await retrieveFacts(stubDb([]), {
      query: "q",
      rerank: () => {
        called = true;
        return Promise.resolve([]);
      },
      tenantId: "tenant-1",
    });
    expect(results).toEqual([]);
    expect(called).toBe(false);
  });
});

