  test("reports estimated usage from the token count it is given", async () => {
    const seen: GatewayUsage[] = [];
    const rerank = createVoyageRerank<{ text: string }>({
      apiKey: "test",
      fetchImpl: () =>
        Promise.resolve(
          new Response(
