      if (!isSearchTool(part)) {
        continue;
      }
      const output = part.output as { facts?: CitedFact[] } | undefined;
      for (const fact of output?.facts ?? []) {
        if (fact?.id) {
          byId.set(fact.id, fact);
        }
      }
    }
  }
  return byId;
};

export const KnowledgeChat = () => {
  const agent = useEveAgent();
  const isBusy = agent.status === "submitted" || agent.status === "streaming";

  const facts = useMemo(
    () => collectFacts(agent.data.messages as never),
    [agent.data.messages]
  );

  const components = useMemo(
    () => ({
      fact: ({ id }: { id?: string }) => <FactCitation facts={facts} id={id} />,
    }),
    [facts]
  );

  // PromptInput owns the textarea and hands back the composed message, so the
  // composer state lives there rather than being mirrored here.
  const submit = useCallback(
    (message: { text?: string }) => {
      const text = message.text?.trim() ?? "";
      if (text.length === 0 || isBusy) {
        return;
      }
      // Rejections surface through agent.error, which the view renders; this
      // catch only keeps the promise from floating.
      agent.send({ message: text }).catch(() => undefined);
    },
    [agent, isBusy]
  );

  return (
    <div className="mx-auto flex h-full w-full max-w-3xl min-w-0 flex-col gap-3">
      <Conversation className="min-h-0 flex-1 rounded-xl border">
        <ConversationContent
          // Center the empty state in the frame; harmless with messages
          // present, but overflowing content must not be justify-centered or
          // its top becomes unreachable.
          className={
            agent.data.messages.length === 0
              ? "min-h-full justify-center"
              : undefined
          }
        >
          {agent.data.messages.length === 0 ? (
            <ConversationEmptyState
              description="Jede Antwort zitiert die Fakten, auf denen sie beruht."
              icon={<BrainIcon className="size-8" />}
              title="Frag das Firmengedächtnis"
            />
          ) : null}

          {agent.data.messages.map((message) => (
            <Message from={message.role} key={message.id}>
              <MessageContent>
                {message.parts.map((part, index) => {
                  if (part.type === "text") {
                    return (
                      <MessageResponse
                        allowedTags={ALLOWED_TAGS}
                        components={components}
                        // biome-ignore lint/suspicious/noArrayIndexKey: stream parts have no stable id and are append-only
                        key={index}
                      >
                        {part.text}
                      </MessageResponse>
                    );
                  }

                  if (isSearchTool(part)) {
                    const tool = part as ToolPart;
                    return (
                      <Tool
                        className="max-w-md"
                        // biome-ignore lint/suspicious/noArrayIndexKey: see above
                        key={index}
                      >
                        <ToolHeader
                          state={tool.state as never}
                          type={tool.type as never}
                        />
                        <ToolContent>
                          <ToolInput input={tool.input} />
                          <ToolOutput
                            errorText={undefined}
                            output={tool.output as never}
                          />
                        </ToolContent>
                      </Tool>
                    );
                  }

                  return null;
                })}
              </MessageContent>
            </Message>
          ))}
        </ConversationContent>
        <ConversationScrollButton />
      </Conversation>

      {agent.error ? (
        <p className="text-destructive text-sm">{agent.error.message}</p>
      ) : null}

      {/* Match the conversation frame's radius on the composer's InputGroup,
          which PromptInput renders internally. */}
      <PromptInput
        className="[&>[data-slot=input-group]]:rounded-xl"
        onSubmit={submit}
      >
        <PromptInputBody>
          <PromptInputTextarea
            className="min-h-0"
            disabled={isBusy}
            placeholder="Was möchtest du wissen?"
          />
        </PromptInputBody>
        <PromptInputFooter className="justify-end">
          <PromptInputSubmit disabled={isBusy} status={agent.status} />
        </PromptInputFooter>
      </PromptInput>
    </div>
  );
};

"use client";

import {
  InlineCitation,
  InlineCitationCard,
  InlineCitationCardBody,
  InlineCitationCardTrigger,
  InlineCitationQuote,
  InlineCitationSource,
} from "@repo/design-system/components/ai-elements/inline-citation";
import { HoverCardTrigger } from "@repo/design-system/components/ui/hover-card";

// Every fact the agent has returned in this conversation, keyed by the id it
// must cite. Built from tool output rather than from the prose, so a claim can
// only cite something the knowledge base actually returned.
export interface CitedFact {
  category: string;
  confidence: number;
  id: string;
  text: string;
  validFrom: string | null;
}

const germanDate = (iso: string | null) =>
  iso
    ? new Date(iso).toLocaleDateString("de-DE", { dateStyle: "medium" })
    : null;

/**
 * Renders one `<fact id="…"/>` marker the model emitted inline.
 *
 * An id we never returned is shown as broken rather than dropped. A dropped
 * citation is indistinguishable from an uncited claim, which is precisely the
 * failure this whole mechanism exists to make visible.
 */
export const FactCitation = ({
  facts,
  id,
}: {
  facts: Map<string, CitedFact>;
  id?: string;
}) => {
  const fact = id ? facts.get(id) : undefined;

  if (!fact) {
    // Same hover-card interaction as a resolved citation, so the broken
    // marker explains itself instead of relying on the native title tooltip.
    return (
      <InlineCitation>
        <InlineCitationCard>
          <HoverCardTrigger asChild>
            <sup
              className="ml-0.5 cursor-help rounded bg-destructive/10 px-1 font-medium text-destructive text-xs"
              tabIndex={0}
            >
              ?
            </sup>
          </HoverCardTrigger>
          <InlineCitationCardBody className="p-3">
            <p className="font-medium text-sm">Unbelegtes Zitat</p>
            <p className="mt-1 text-muted-foreground text-xs">
              {id
                ? `Die Antwort zitiert Fakt ${id}, den die Wissensdatenbank in dieser Unterhaltung nicht geliefert hat. Diese Aussage ist damit nicht belegt.`
                : "Die Antwort enthält ein Zitat ohne Fakt-ID. Diese Aussage ist damit nicht belegt."}
            </p>
          </InlineCitationCardBody>
        </InlineCitationCard>
      </InlineCitation>
    );
  }

  const since = germanDate(fact.validFrom);

  return (
    <InlineCitation>
      <InlineCitationCard>
        <InlineCitationCardTrigger sources={[fact.category]} />
        <InlineCitationCardBody>
          <InlineCitationSource
            description={since ? `gültig seit ${since}` : undefined}
            title={fact.category}
          >
            <p className="text-muted-foreground text-xs">
              Konfidenz {Math.round(fact.confidence * 100)}%
            </p>
          </InlineCitationSource>
          <InlineCitationQuote>{fact.text}</InlineCitationQuote>
        </InlineCitationCardBody>
      </InlineCitationCard>
    </InlineCitation>
  );
};

