                          <ToolInput input={tool.input} />
                          <ToolOutput
                            errorText={tool.errorText}
                            output={tool.output as never}
                          />
                        </ToolContent>
                      </Tool>
                    );
                  }

                  return null;
                })}
              </MessageContent>
            </Message>
          ))}
