// Throwaway: seed a couple of facts for the Playwright debug tenant so the
// ask surface has something to retrieve. Run with:
//   KNOWLEDGE_MONGODB_URI=... bun .context/seed-debug-tenant.ts <tenantId>
import { MongoClient, ObjectId } from "mongodb";
import { getCollections } from "../collections";
import { personSchema } from "../schemas/entities";
import { factSchema } from "../schemas/facts";
import { sourceSchema } from "../schemas/sources";

const tenantId = process.argv[2];
if (!tenantId) {
  throw new Error("usage: bun seed-debug-tenant.ts <tenantId>");
}
const uri = process.env.KNOWLEDGE_MONGODB_URI;
if (!uri) {
  throw new Error("KNOWLEDGE_MONGODB_URI missing");
}

const client = new MongoClient(uri);
const db = client.db();
const { facts, people, sources } = getCollections(db);
const now = new Date();
const base = { createdAt: now, tenantId, updatedAt: now };

const person = personSchema.parse({
  ...base,
  _id: new ObjectId(),
  emails: ["karla@testmann.example"],
  name: "Karla Testmann",
  role: "Projektleiterin",
});

const source = sourceSchema.parse({
  ...base,
  _id: new ObjectId(),
  capturedBy: "claude-debug@example.com",
  content:
    "Debug-Notiz: Karla Testmann bevorzugt Videocalls am Dienstagvormittag. Ihr Budgetrahmen für das Pilotprojekt liegt bei 25.000 Euro.",
  status: "reviewed",
  type: "manual",
});

const factDocs = [
  "Karla Testmann bevorzugt Videocalls am Dienstagvormittag.",
  "Der Budgetrahmen für Karla Testmanns Pilotprojekt liegt bei 25.000 Euro.",
].map((text, index) =>
  factSchema.parse({
    ...base,
    _id: new ObjectId(),
    anchors: { personId: person._id },
    category: index === 0 ? "preference" : "logistics",
    confidence: 0.95,
    confirmedBy: "claude-debug@example.com",
    sourceId: source._id,
    text,
    validFrom: now,
  })
);

await people.insertOne(person);
await sources.insertOne(source);
await facts.insertMany(factDocs);
console.log(
  "seeded",
  factDocs.map((f) => f._id.toHexString()),
  "person",
  person._id.toHexString()
);
await client.close();

