() => {
  const root = document.querySelector('[role="log"]');
  if (!root) return 'no log';
  const fiberKey = Object.keys(root).find(k => k.startsWith('__reactFiber$'));
  if (!fiberKey) return 'no fiber';
  let fiber = root[fiberKey];
  // walk up to a component whose props include messages
  const seen = new Set();
  const queue = [fiber];
  let messages = null;
  while (fiber && fiber.return) fiber = fiber.return; // go to root
  const walk = (f, depth) => {
    if (!f || depth > 60 || seen.has(f)) return;
    seen.add(f);
    const props = f.memoizedProps;
    if (props && props.children === undefined && Array.isArray(props.messages)) { messages = props.messages; return; }
    walk(f.child, depth + 1);
    walk(f.sibling, depth);
  };
  walk(fiber, 0);
  // fallback: find any fiber with memoizedState containing messages
  if (!messages) {
    seen.clear();
    const walk2 = (f, depth) => {
      if (!f || depth > 80 || seen.has(f) || messages) return;
      seen.add(f);
      let s = f.memoizedState;
      let hops = 0;
      while (s && hops < 40 && !messages) {
        const val = s.memoizedState;
        if (val && typeof val === 'object' && Array.isArray(val.messages)) messages = val.messages;
        if (Array.isArray(val) && val[0] && val[0].role && val[0].parts) messages = val;
        s = s.next; hops++;
      }
      walk2(f.child, depth + 1);
      walk2(f.sibling, depth);
    };
    walk2(fiber, 0);
  }
  if (!messages) return 'messages not found in fiber tree';
  const last = messages[messages.length - 1];
  const toolParts = (last.parts || []).filter(p => p.type && p.type !== 'text' && p.type !== 'reasoning' && p.type !== 'step-start');
  return JSON.stringify({ partTypes: (last.parts || []).map(p => p.type), firstToolPart: toolParts[0] }, null, 1).slice(0, 2500);
}

