() => {
  const sups = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === '?');
  if (sups.length === 0) return 'no ? buttons';
  const el = sups[0];
  const key = Object.keys(el).find(k => k.startsWith('__reactFiber$'));
  let f = el[key];
  const report = [];
  for (let up = 0; f && up < 25; up++, f = f.return) {
    const name = typeof f.type === 'function' ? (f.type.displayName || f.type.name || 'anon') : String(f.type);
    const props = f.memoizedProps && typeof f.memoizedProps === 'object' ? Object.keys(f.memoizedProps) : [];
    let extra = '';
    if (props.includes('id')) extra += ' id=' + JSON.stringify(f.memoizedProps.id);
    if (props.includes('facts')) {
      const facts = f.memoizedProps.facts;
      extra += ' factsType=' + (facts instanceof Map ? 'Map(' + facts.size + '):[' + [...facts.keys()].join(',') + ']' : typeof facts);
    }
    report.push(name + ' {' + props.join(',') + '}' + extra);
  }
  return report.join('\n');
}

