() => {
  const log = document.querySelector('[role="log"]');
  const report = { window: { scrollY: window.scrollY, docScrollable: document.documentElement.scrollHeight - window.innerHeight } };
  let el = log;
  const chain = [];
  // find scrollable descendants of the log
  const descendants = [log, ...log.querySelectorAll('*')].filter(e => e.scrollHeight > e.clientHeight + 2);
  report.scrollableInsideLog = descendants.slice(0, 4).map(e => ({
    tag: e.tagName, cls: (e.className || '').toString().slice(0, 80),
    scrollHeight: e.scrollHeight, clientHeight: e.clientHeight, scrollTop: e.scrollTop,
    overflowY: getComputedStyle(e).overflowY,
  }));
  // find scrollable ancestors
  el = log.parentElement;
  while (el && el !== document.body) {
    if (el.scrollHeight > el.clientHeight + 2) {
      chain.push({ tag: el.tagName, cls: (el.className || '').toString().slice(0, 80), scrollHeight: el.scrollHeight, clientHeight: el.clientHeight, scrollTop: el.scrollTop, overflowY: getComputedStyle(el).overflowY });
    }
    el = el.parentElement;
  }
  report.scrollableAncestors = chain;
  report.logBox = { scrollHeight: log.scrollHeight, clientHeight: log.clientHeight, overflowY: getComputedStyle(log).overflowY };
  return JSON.stringify(report, null, 1);
}

